//! Byte-exact codec for the SPAWN! wire format.
//!
//! The EVM sides exchange `abi.encode(uint8 op, bytes inner)` where `inner`
//! is `abi.encode(<op's tuple>)` — Solidity's standard head/tail ABI
//! encoding. This module reproduces it bit-for-bit in both directions; the
//! cross-vectors in `solana/tests/codec-vectors.json` (generated by the SAME
//! AbiCoder the contracts compile against) are the proof.
//!
//! WIRE CONVENTION (protocol v4): every account rider is a `bytes32`
//! (`WireAddr`) — token ids, creators, recipients, all of them. EVM
//! addresses ride left-padded with zeros; Solana pubkeys ride raw, so this
//! leg consumes recipients directly as `Pubkey`s. The EVM side enforces its
//! own downcast rule on receive ("PAD: bad recipient"); here every 32-byte
//! value is legal.

use crate::error::GatewayError;
use anchor_lang::prelude::*;

pub const OP_SPAWN: u8 = 1;
pub const OP_BUY: u8 = 2;
pub const OP_SELL: u8 = 3;
pub const OP_CLAIM: u8 = 4;
/// v7, additive: a chain asks the hub for its waiting holder fees.
pub const OP_PULL_FEES: u8 = 5;
pub const OP_SYNC_TOKEN: u8 = 10;
pub const OP_DELIVER: u8 = 11;
pub const OP_PAYOUT: u8 = 12;
pub const OP_FEE_DROP: u8 = 13;

/// A full 32-byte wire account rider. For EVM-origin values the top 12
/// bytes are zero; for Solana recipients it IS the pubkey.
#[derive(Clone, Copy, PartialEq, Eq, Debug, AnchorSerialize, AnchorDeserialize)]
pub struct WireAddr(pub [u8; 32]);

impl WireAddr {
    pub fn pubkey(&self) -> Pubkey {
        Pubkey::new_from_array(self.0)
    }

    pub fn from_pubkey(p: &Pubkey) -> Self {
        Self(p.to_bytes())
    }
}

/// A full-width EVM uint256, big-endian. Kept raw; amounts convert to u64
/// explicitly through the decimal bridge (`to_spl_amount`).
#[derive(Clone, Copy, PartialEq, Eq, Debug, AnchorSerialize, AnchorDeserialize)]
pub struct U256(pub [u8; 32]);

impl U256 {
    pub fn from_u128(v: u128) -> Self {
        let mut w = [0u8; 32];
        w[16..].copy_from_slice(&v.to_be_bytes());
        Self(w)
    }

    pub fn is_zero(&self) -> bool {
        self.0 == [0u8; 32]
    }

    /// The value as u128, or None if it needs more than 128 bits.
    pub fn as_u128(&self) -> Option<u128> {
        if self.0[..16] != [0u8; 16] {
            return None;
        }
        Some(u128::from_be_bytes(self.0[16..].try_into().unwrap()))
    }

    /// Decimal bridge, EVM → SPL: divide by 1e12 (floor — the sub-unit dust
    /// is never minted) and require the result to fit u64.
    pub fn to_spl_amount(&self) -> Result<u64> {
        let v = self.as_u128().ok_or(GatewayError::AmountOverflow)?;
        let scaled = v / crate::EVM_TO_SPL_DIVISOR;
        u64::try_from(scaled).map_err(|_| GatewayError::AmountOverflow.into())
    }

    /// Decimal bridge, EVM → SPL, keeping what the floor drops: whole SPL
    /// units and the sub-unit remainder in 18-decimal wei.
    pub fn split_spl(&self) -> Result<(u64, u128)> {
        let v = self.as_u128().ok_or(GatewayError::AmountOverflow)?;
        let units = u64::try_from(v / crate::EVM_TO_SPL_DIVISOR)
            .map_err(|_| GatewayError::AmountOverflow)?;
        Ok((units, v % crate::EVM_TO_SPL_DIVISOR))
    }

    /// Decimal bridge, SPL → EVM: multiply by 1e12 (cannot overflow: u64 ×
    /// 1e12 < 2^104).
    pub fn from_spl_amount(amount: u64) -> Self {
        Self::from_u128(amount as u128 * crate::EVM_TO_SPL_DIVISOR)
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum SpawnMsg {
    /// (creator, name, symbol, metaURI, devBuyUsd, feeMode)
    Spawn { creator: WireAddr, name: String, symbol: String, meta_uri: String, dev_buy_usd: U256, fee_mode: u8 },
    /// (hubToken, buyer, usdIn)
    Buy { hub_token: WireAddr, buyer: WireAddr, usd_in: U256 },
    /// (hubToken, seller, tokensIn)
    Sell { hub_token: WireAddr, seller: WireAddr, tokens_in: U256 },
    /// (hubToken, claimer)
    Claim { hub_token: WireAddr, claimer: WireAddr },
    /// (hubToken) — v7: bring this chain's waiting holder fees home
    PullFees { hub_token: WireAddr },
    /// (hubToken, name, symbol)
    SyncToken { hub_token: WireAddr, name: String, symbol: String },
    /// (hubToken, to, tokens, refund)
    Deliver { hub_token: WireAddr, to: WireAddr, tokens: U256, refund: U256 },
    /// (to, usdOut)
    Payout { to: WireAddr, usd_out: U256 },
    /// (hubToken, amount)
    FeeDrop { hub_token: WireAddr, amount: U256 },
}

/* ------------------------------- writer ------------------------------- */

#[derive(Default)]
struct AbiWriter {
    head: Vec<Head>,
    n_slots: usize,
}

enum Head {
    Word([u8; 32]),
    Dynamic(Vec<u8>), // tail bytes of one dynamic value (len word + padded data)
}

impl AbiWriter {
    fn word(&mut self, w: [u8; 32]) {
        self.head.push(Head::Word(w));
        self.n_slots += 1;
    }

    fn address(&mut self, a: &WireAddr) {
        self.word(a.0);
    }

    fn uint(&mut self, u: &U256) {
        self.word(u.0);
    }

    fn u8_word(&mut self, v: u8) {
        let mut w = [0u8; 32];
        w[31] = v;
        self.word(w);
    }

    fn bytes_like(&mut self, data: &[u8]) {
        let mut tail = Vec::with_capacity(32 + data.len().div_ceil(32) * 32);
        let mut len = [0u8; 32];
        len[24..].copy_from_slice(&(data.len() as u64).to_be_bytes());
        tail.extend_from_slice(&len);
        tail.extend_from_slice(data);
        tail.resize(32 + data.len().div_ceil(32) * 32, 0);
        self.head.push(Head::Dynamic(tail));
        self.n_slots += 1;
    }

    fn string(&mut self, s: &str) {
        self.bytes_like(s.as_bytes());
    }

    fn finish(self) -> Vec<u8> {
        let head_len = self.n_slots * 32;
        let mut head = Vec::with_capacity(head_len);
        let mut tail = Vec::new();
        for h in self.head {
            match h {
                Head::Word(w) => head.extend_from_slice(&w),
                Head::Dynamic(bytes) => {
                    let mut off = [0u8; 32];
                    off[24..].copy_from_slice(&((head_len + tail.len()) as u64).to_be_bytes());
                    head.extend_from_slice(&off);
                    tail.extend_from_slice(&bytes);
                }
            }
        }
        head.extend_from_slice(&tail);
        head
    }
}

impl SpawnMsg {
    pub fn op(&self) -> u8 {
        match self {
            SpawnMsg::Spawn { .. } => OP_SPAWN,
            SpawnMsg::Buy { .. } => OP_BUY,
            SpawnMsg::Sell { .. } => OP_SELL,
            SpawnMsg::Claim { .. } => OP_CLAIM,
            SpawnMsg::PullFees { .. } => OP_PULL_FEES,
            SpawnMsg::SyncToken { .. } => OP_SYNC_TOKEN,
            SpawnMsg::Deliver { .. } => OP_DELIVER,
            SpawnMsg::Payout { .. } => OP_PAYOUT,
            SpawnMsg::FeeDrop { .. } => OP_FEE_DROP,
        }
    }

    fn encode_inner(&self) -> Vec<u8> {
        let mut w = AbiWriter::default();
        match self {
            SpawnMsg::Spawn { creator, name, symbol, meta_uri, dev_buy_usd, fee_mode } => {
                w.address(creator);
                w.string(name);
                w.string(symbol);
                w.string(meta_uri);
                w.uint(dev_buy_usd);
                w.u8_word(*fee_mode);
            }
            SpawnMsg::Buy { hub_token, buyer, usd_in } => {
                w.address(hub_token);
                w.address(buyer);
                w.uint(usd_in);
            }
            SpawnMsg::Sell { hub_token, seller, tokens_in } => {
                w.address(hub_token);
                w.address(seller);
                w.uint(tokens_in);
            }
            SpawnMsg::Claim { hub_token, claimer } => {
                w.address(hub_token);
                w.address(claimer);
            }
            SpawnMsg::PullFees { hub_token } => {
                w.address(hub_token);
            }
            SpawnMsg::SyncToken { hub_token, name, symbol } => {
                w.address(hub_token);
                w.string(name);
                w.string(symbol);
            }
            SpawnMsg::Deliver { hub_token, to, tokens, refund } => {
                w.address(hub_token);
                w.address(to);
                w.uint(tokens);
                w.uint(refund);
            }
            SpawnMsg::Payout { to, usd_out } => {
                w.address(to);
                w.uint(usd_out);
            }
            SpawnMsg::FeeDrop { hub_token, amount } => {
                w.address(hub_token);
                w.uint(amount);
            }
        }
        w.finish()
    }

    /// The full envelope: abi.encode(uint8 op, bytes inner).
    pub fn encode(&self) -> Vec<u8> {
        let inner = self.encode_inner();
        let mut w = AbiWriter::default();
        w.u8_word(self.op());
        w.bytes_like(&inner);
        w.finish()
    }

    pub fn decode(payload: &[u8]) -> Result<Self> {
        let env = AbiReader::new(payload);
        let op_word = env.word_at(0)?;
        require!(op_word[..31] == [0u8; 31], GatewayError::BadPayload);
        let op = op_word[31];
        let inner = env.bytes_at(1)?;
        let r = AbiReader::new(inner);
        Ok(match op {
            OP_SPAWN => SpawnMsg::Spawn {
                creator: r.address_at(0)?,
                name: r.string_at(1)?,
                symbol: r.string_at(2)?,
                meta_uri: r.string_at(3)?,
                dev_buy_usd: r.uint_at(4)?,
                fee_mode: r.u8_at(5)?,
            },
            OP_BUY => SpawnMsg::Buy {
                hub_token: r.address_at(0)?,
                buyer: r.address_at(1)?,
                usd_in: r.uint_at(2)?,
            },
            OP_SELL => SpawnMsg::Sell {
                hub_token: r.address_at(0)?,
                seller: r.address_at(1)?,
                tokens_in: r.uint_at(2)?,
            },
            OP_CLAIM => SpawnMsg::Claim { hub_token: r.address_at(0)?, claimer: r.address_at(1)? },
            OP_PULL_FEES => SpawnMsg::PullFees { hub_token: r.address_at(0)? },
            OP_SYNC_TOKEN => SpawnMsg::SyncToken {
                hub_token: r.address_at(0)?,
                name: r.string_at(1)?,
                symbol: r.string_at(2)?,
            },
            OP_DELIVER => SpawnMsg::Deliver {
                hub_token: r.address_at(0)?,
                to: r.address_at(1)?,
                tokens: r.uint_at(2)?,
                refund: r.uint_at(3)?,
            },
            OP_PAYOUT => SpawnMsg::Payout { to: r.address_at(0)?, usd_out: r.uint_at(1)? },
            OP_FEE_DROP => SpawnMsg::FeeDrop { hub_token: r.address_at(0)?, amount: r.uint_at(1)? },
            _ => return Err(GatewayError::UnknownOp.into()),
        })
    }
}

/* ------------------------------ envelope ------------------------------ */

/// The inter-transport envelope (v5): `abi.encode(bytes32 srcSender,
/// bytes32 dstAddr, bytes payload)` — wide on both seats, so a Solana OApp
/// store can be the sender or the target. EVM adapters produce and consume
/// this exact layout; we wrap every send and unwrap every receive with it.
#[derive(Debug, PartialEq, Eq)]
pub struct Envelope {
    pub src_sender: WireAddr,
    pub dst_addr: WireAddr,
    pub payload: Vec<u8>,
}

impl Envelope {
    pub fn encode(&self) -> Vec<u8> {
        let mut w = AbiWriter::default();
        w.address(&self.src_sender);
        w.address(&self.dst_addr);
        w.bytes_like(&self.payload);
        w.finish()
    }

    pub fn decode(message: &[u8]) -> Result<Self> {
        let r = AbiReader::new(message);
        Ok(Self {
            src_sender: r.address_at(0)?,
            dst_addr: r.address_at(1)?,
            payload: r.bytes_at(2)?.to_vec(),
        })
    }
}

/* ------------------------------- options ------------------------------ */

/// The executor options of one send (v7), bit-for-bit what the EVM adapters
/// pack in `LayerZeroOmniMessenger._packet`: a type-3 container with ONE
/// executor lzReceive option — `gas` for the destination's lzReceive, and,
/// when non-zero, `value` in DESTINATION native currency delivered into the
/// receiving adapter together with the message (the reply budget).
pub fn lz_receive_options(gas: u128, value: u128) -> Vec<u8> {
    let mut o = Vec::with_capacity(38);
    o.extend_from_slice(&3u16.to_be_bytes()); // options type 3
    o.push(1); // worker id: executor
    if value == 0 {
        o.extend_from_slice(&17u16.to_be_bytes()); // option size: type + gas
        o.push(1); // option type: lzReceive
        o.extend_from_slice(&gas.to_be_bytes());
    } else {
        o.extend_from_slice(&33u16.to_be_bytes()); // type + gas + value
        o.push(1);
        o.extend_from_slice(&gas.to_be_bytes());
        o.extend_from_slice(&value.to_be_bytes());
    }
    o
}

/* ------------------------------- reader ------------------------------- */

/// Strict reader for canonical abi.encode output: offsets must land in
/// bounds, u8 words must be zero-padded, strings must be UTF-8. Account
/// riders are raw 32-byte words — never rejected. (The only producer is our
/// own hub contract, so strictness elsewhere costs nothing and catches
/// corruption early.)
struct AbiReader<'a> {
    data: &'a [u8],
}

impl<'a> AbiReader<'a> {
    fn new(data: &'a [u8]) -> Self {
        Self { data }
    }

    fn word_at(&self, slot: usize) -> Result<[u8; 32]> {
        let start = slot * 32;
        let end = start + 32;
        require!(end <= self.data.len(), GatewayError::BadPayload);
        Ok(self.data[start..end].try_into().unwrap())
    }

    fn uint_at(&self, slot: usize) -> Result<U256> {
        Ok(U256(self.word_at(slot)?))
    }

    fn address_at(&self, slot: usize) -> Result<WireAddr> {
        // any 32-byte value is a legal rider (Solana pubkeys use every byte)
        Ok(WireAddr(self.word_at(slot)?))
    }

    fn u8_at(&self, slot: usize) -> Result<u8> {
        let w = self.word_at(slot)?;
        require!(w[..31] == [0u8; 31], GatewayError::BadPayload);
        Ok(w[31])
    }

    fn offset_at(&self, slot: usize) -> Result<usize> {
        let w = self.word_at(slot)?;
        require!(w[..24] == [0u8; 24], GatewayError::BadPayload);
        let off = u64::from_be_bytes(w[24..].try_into().unwrap()) as usize;
        require!(off % 32 == 0 && off + 32 <= self.data.len(), GatewayError::BadPayload);
        Ok(off)
    }

    fn bytes_at(&self, slot: usize) -> Result<&'a [u8]> {
        let off = self.offset_at(slot)?;
        let len_w: [u8; 32] = self.data[off..off + 32].try_into().unwrap();
        require!(len_w[..24] == [0u8; 24], GatewayError::BadPayload);
        let len = u64::from_be_bytes(len_w[24..].try_into().unwrap()) as usize;
        let start = off + 32;
        require!(start + len <= self.data.len(), GatewayError::BadPayload);
        Ok(&self.data[start..start + len])
    }

    fn string_at(&self, slot: usize) -> Result<String> {
        let bytes = self.bytes_at(slot)?;
        String::from_utf8(bytes.to_vec()).map_err(|_| GatewayError::BadPayload.into())
    }
}

/* -------------------------------- tests ------------------------------- */

#[cfg(test)]
mod tests {
    use super::*;

    fn unhex(s: &str) -> Vec<u8> {
        let s = s.trim_start_matches("0x");
        (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
    }

    fn addr(v: &serde_json::Value) -> WireAddr {
        // vectors emit bytes32 riders as 32-byte hex
        WireAddr(unhex(v.as_str().unwrap()).try_into().unwrap())
    }

    fn uint(v: &serde_json::Value) -> U256 {
        U256(unhex(v.as_str().unwrap()).try_into().unwrap())
    }

    fn s(v: &serde_json::Value) -> String {
        v.as_str().unwrap().to_string()
    }

    /// Every vector was produced by ethers' AbiCoder — the same coder solc
    /// compiles into our hub. Byte-exact both ways, and semantically equal
    /// to the JSON's field values.
    #[test]
    fn cross_vectors_round_trip() {
        let raw = include_str!("../../../tests/codec-vectors.json");
        let file: serde_json::Value = serde_json::from_str(raw).unwrap();
        let vectors = file["ops"].as_array().unwrap();
        assert!(vectors.len() >= 29, "vector file looks truncated");
        // v7's additive op must be in the file
        assert!(vectors.iter().any(|v| v["name"] == "PULL_FEES"));
        // the file must exercise wide (Solana-shaped) riders too
        assert!(vectors.iter().any(|v| v["wide"].as_bool() == Some(true)));
        for v in vectors {
            let bytes = unhex(v["hex"].as_str().unwrap());
            let i = &v["inner"];
            let expected = match v["name"].as_str().unwrap() {
                "SPAWN" => SpawnMsg::Spawn {
                    creator: addr(&i[0]),
                    name: s(&i[1]),
                    symbol: s(&i[2]),
                    meta_uri: s(&i[3]),
                    dev_buy_usd: uint(&i[4]),
                    fee_mode: i[5].as_u64().unwrap() as u8,
                },
                "BUY" => SpawnMsg::Buy { hub_token: addr(&i[0]), buyer: addr(&i[1]), usd_in: uint(&i[2]) },
                "SELL" => SpawnMsg::Sell { hub_token: addr(&i[0]), seller: addr(&i[1]), tokens_in: uint(&i[2]) },
                "CLAIM" => SpawnMsg::Claim { hub_token: addr(&i[0]), claimer: addr(&i[1]) },
                "PULL_FEES" => SpawnMsg::PullFees { hub_token: addr(&i[0]) },
                "SYNC_TOKEN" => SpawnMsg::SyncToken { hub_token: addr(&i[0]), name: s(&i[1]), symbol: s(&i[2]) },
                "DELIVER" => SpawnMsg::Deliver { hub_token: addr(&i[0]), to: addr(&i[1]), tokens: uint(&i[2]), refund: uint(&i[3]) },
                "PAYOUT" => SpawnMsg::Payout { to: addr(&i[0]), usd_out: uint(&i[1]) },
                "FEE_DROP" => SpawnMsg::FeeDrop { hub_token: addr(&i[0]), amount: uint(&i[1]) },
                other => panic!("unknown vector {other}"),
            };
            let decoded = SpawnMsg::decode(&bytes)
                .unwrap_or_else(|e| panic!("vector {} failed to decode: {e}", v["idx"]));
            assert_eq!(decoded, expected, "vector {} decoded wrong", v["idx"]);
            assert_eq!(decoded.op(), v["op"].as_u64().unwrap() as u8);
            assert_eq!(decoded.encode(), bytes, "vector {} re-encoded differently", v["idx"]);
        }
    }

    #[test]
    fn decimal_bridge() {
        // 884495.291384607698648615 × 1e18 floors to 884495291384 micro-units
        let v = U256::from_u128(884_495_291_384_607_698_648_615);
        assert_eq!(v.to_spl_amount().unwrap(), 884_495_291_384);
        // round-trips lose only sub-1e-6 dust
        assert_eq!(U256::from_spl_amount(884_495_291_384).as_u128().unwrap(), 884_495_291_384_000_000_000_000);
        // u256 too big for the bridge must refuse, not wrap
        assert!(U256([0xff; 32]).to_spl_amount().is_err());
        // max supply still fits comfortably
        let billion = U256::from_u128(1_000_000_000 * 10u128.pow(18));
        assert_eq!(billion.to_spl_amount().unwrap(), 1_000_000_000 * 10u64.pow(6));
    }

    #[test]
    fn rejects_garbage() {
        assert!(SpawnMsg::decode(&[]).is_err());
        assert!(SpawnMsg::decode(&[0u8; 63]).is_err());
        // unknown op
        let msg = SpawnMsg::Payout { to: WireAddr([1; 32]), usd_out: U256::from_u128(1) };
        let mut bytes = msg.encode();
        bytes[31] = 99;
        assert!(SpawnMsg::decode(&bytes).is_err());
        // dirty inner-offset word still rejects
        let mut bytes = msg.encode();
        bytes[33] = 1; // inside the envelope offset word's high padding
        assert!(SpawnMsg::decode(&bytes).is_err());
    }

    /// The envelope vectors come from the same ethers coder the EVM
    /// adapters compile against — both directions, byte-exact.
    #[test]
    fn envelope_vectors_round_trip() {
        let raw = include_str!("../../../tests/codec-vectors.json");
        let file: serde_json::Value = serde_json::from_str(raw).unwrap();
        let envs = file["envelopes"].as_array().unwrap();
        assert!(envs.len() >= 3, "envelope vectors missing");
        for v in envs {
            let bytes = unhex(v["hex"].as_str().unwrap());
            let expected = Envelope {
                src_sender: addr(&v["src"]),
                dst_addr: addr(&v["dst"]),
                payload: unhex(v["payload"].as_str().unwrap()),
            };
            let decoded = Envelope::decode(&bytes)
                .unwrap_or_else(|e| panic!("envelope {} failed to decode: {e}", v["name"]));
            assert_eq!(decoded, expected, "envelope {} decoded wrong", v["name"]);
            assert_eq!(decoded.encode(), bytes, "envelope {} re-encoded differently", v["name"]);
            // and the payload inside is itself a decodable op
            assert!(SpawnMsg::decode(&decoded.payload).is_ok());
        }
    }

    /// The executor options must be the bytes the EVM adapters pack
    /// (ethers' solidityPacked ≡ abi.encodePacked), with and without a
    /// reply budget.
    #[test]
    fn option_vectors_match_the_evm_adapters() {
        let raw = include_str!("../../../tests/codec-vectors.json");
        let file: serde_json::Value = serde_json::from_str(raw).unwrap();
        let opts = file["options"].as_array().unwrap();
        assert!(opts.len() >= 4, "option vectors missing");
        for v in opts {
            let gas: u128 = v["gas"].as_str().unwrap().parse().unwrap();
            let value: u128 = v["value"].as_str().unwrap().parse().unwrap();
            assert_eq!(lz_receive_options(gas, value), unhex(v["hex"].as_str().unwrap()), "option {}", v["idx"]);
        }
        assert_eq!(lz_receive_options(1, 0).len(), 22);
        assert_eq!(lz_receive_options(1, 1).len(), 38);
    }

    /// The point of the bytes32 evolution: a full Solana pubkey rides the
    /// wire untouched — high bytes set, no padding rule, byte-exact.
    #[test]
    fn wide_riders_are_legal() {
        let to = WireAddr([0xEE; 32]);
        let msg = SpawnMsg::Payout { to, usd_out: U256::from_u128(7) };
        let decoded = SpawnMsg::decode(&msg.encode()).unwrap();
        assert_eq!(decoded, msg);
        match decoded {
            SpawnMsg::Payout { to, .. } => assert_eq!(to.pubkey().to_bytes(), [0xEE; 32]),
            _ => unreachable!(),
        }
    }
}
